def _q(qid, split, category, text, truth, clarify_answer=None):
    return {"id": qid, "split": split, "category": category, "text": text,
            "clarify_answer": clarify_answer, "truth": truth}  # fmt: skip


def _t(printings, budget=None, min_condition=None, persona="cautious_buyer", **extra):
    return {"printings": printings, "budget": budget, "min_condition": min_condition,
            "persona": persona, **extra}  # fmt: skip


